lists = [["d1", "d2", "d3"], ["d2", "d4", "d1"], ["d3", "d1", "d5"]]
K = 60
scores = {}
for lst in lists:
    for rank, doc in enumerate(lst, start=1):
        scores[doc] = scores.get(doc, 0.0) + 1.0 / (K + rank)
for doc, s in sorted(scores.items(), key=lambda kv: -kv[1]):
    print("%s fused=%.4f" % (doc, s))

