import re
raw = 'title:archive "deep search" lang:en -draft'
model = {"terms": [], "phrases": [], "filters": {}, "exclude": []}
for ph in re.findall(r'"([^"]+)"', raw):
    model["phrases"].append(ph.lower())
txt = re.sub(r'"[^"]+"', " ", raw)
for tok in txt.split():
    if ":" in tok:
        k, v = tok.split(":", 1); model["filters"][k] = v
    elif tok.startswith("-"):
        model["exclude"].append(tok[1:])
    else:
        model["terms"].append(tok.lower())
print(model)

