REGISTRY = {
  "alpha": {"fields": ["title", "body"], "ops": ["AND", "OR", "phrase"], "ms": 120},
  "beta":  {"fields": ["title"], "ops": ["AND"], "ms": 40},
  "gamma": {"fields": ["title", "body", "tags"], "ops": ["AND", "OR"], "ms": 300},
}
need_fields, need_ops = {"title", "body"}, {"phrase"}
chosen = [n for n, c in REGISTRY.items()
          if need_fields <= set(c["fields"]) and need_ops <= set(c["ops"])]
print("capable sources:", chosen)
print("fastest:", min(chosen, key=lambda n: REGISTRY[n]["ms"]))

