import hashlib, re
def norm(s): return re.sub(r"\s+", " ", s.strip().lower())
docs = [("alpha", "Deep Search of Archives"), ("beta", "deep search of archives "),
        ("gamma", "Archive Cartography Methods")]
groups = {}
for src, text in docs:
    h = hashlib.sha256(norm(text).encode()).hexdigest()[:12]
    groups.setdefault(h, []).append(src)
for h, srcs in groups.items():
    print(h, "held by:", ", ".join(srcs))

